#!/usr/bin/env python3
"""Run C2 Unit02 recalibration with narrow target-safe depth extensions."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c2_unit02.py')
text=SOURCE.read_text(encoding='utf-8')
marker='UPDATES={'
assert text.count(marker)==1
EXTRA={
'ar-c2-u02-p02':"""وفي مراجعة لاحقة أخذ فريق مستقل عينة من القرارات القديمة وأخفى اسم الجهة وحجمها، ثم أعاد تقييمها باستعمال العوامل المباشرة وحدها. عندما اختلفت النتيجة عن الترتيب السابق، طُلب من الموظفين شرح أي معلومة كان الحجم يضيفها فعلًا. في بعض الملفات لم يضف شيئًا، وفي ملفات أخرى كان مجرد علامة أولية تدفع إلى جمع معلومات إضافية. أضافت اللجنة لذلك خانة تسجل سبب استعمال كل مؤشر والظرف الذي يفقد فيه قيمته. كما اشترطت مراجعة دورية للحالات الشاذة حتى لا تتحول الخبرة المتراكمة إلى قاعدة مغلقة لا ترى إلا الأمثلة التي تؤكدها. بهذه الآلية بقي للإدارة مجال التعلم، لكن صار التعلم نفسه قابلًا للفحص والتصحيح.""",
'ar-c2-u02-p03':"""وفي جلسة أخيرة أعطت الهيئة العقد لفريق لم يعرف النزاع الأصلي، وطلبت منه تحديد وظيفة كل مسار قبل رؤية الرسوم المختلف عليها. جاءت الخريطة قريبة من التحليل السابق، لكنها كشفت بندًا صغيرًا يسمح بإجراء مؤقت عند خطر على البيانات. لم يغير ذلك النتيجة مباشرة، لكنه أكد أن الوثيقة توزع السلطة بحسب وظيفة المشكلة لا بحسب كونها مالية أو تقنية فقط. ثم اختبر الفريق قاعدة كل طرف على حالة لم يتوقعها: تكلفة إصلاح تظهر بعد القبول لكنها تعود إلى خلل حدث أثناء الاختبار. أجبر المثال الطرفين على توضيح أي زمن يهمهما: زمن نشوء السبب، أم زمن حساب المبلغ، أم زمن اكتشاف الخلل. جعل هذا التحديد قاعدة النطاق أكثر شفافية وقابلية للتطبيق خارج القضية الأولى.""",
'ar-c2-u02-p04':"""ولمعرفة هل الفصل المقترح يعمل فعليًا، طبقت الرابطة نموذجًا تجريبيًا على عدة ملفات قديمة من دون تغيير النتائج. في الحالات البسيطة لم يضف المراجع المستقل وقتًا يذكر، أما في القضايا التي تعتمد على شهادات متعارضة فقد كشف أسئلة لم تطرحها اللجنة الأولى لأنها بنت فرضية مبكرة. لم تعتبر الهيئة ذلك دليلًا على سوء نية، بل على أثر طبيعي لتراكم الأدوار. لذلك أوصت بتدوير المسؤوليات وتسجيل الأسئلة التي طرحت في كل مرحلة، مع إمكان تخفيف الإجراء عندما تكون الوقائع غير متنازع عليها والعقوبة محدودة. الهدف هو أن تتناسب البنية مع مصدر الخطأ المتوقع، لا أن يصبح التعقيد قيمة في ذاته أو أن يبقى الإجراء البسيط مثقلًا بحماية لا تؤدي وظيفة واضحة.""",
'ar-c2-u02-p05':"""وأجرت الهيئة اختبارًا آخر على سلسلة الحفظ. طلبت من خبير تقني مستقل إعادة إنتاج التحويل من النسخة الأقدم إلى الصيغة اللاحقة باستخدام إعدادات النظام المحفوظة. تكرر سقوط الفقرة نفسها، فازدادت قوة تفسير الخطأ الفني، لكن الهيئة سجلت أيضًا أن إعادة الإنتاج لا تجيب عن معنى العبارة أو سلطة كاتبها. ثم قارنت السجلات الزمنية مع فواتير العمل وتواريخ تسليم الخدمة، فوجدت توافقًا في بعض النقاط واختلافًا في أخرى. أصبح الملف أقوى في إثبات أن عملًا إضافيًا حدث، وأضعف في إثبات أن كل تكلفته قُبلت بالطريقة التي يقولها أحد الأطراف. هذا الفصل بين ما يقويه الاختبار وما يتركه مفتوحًا منع نتيجة تقنية واحدة من التمدد إلى مسائل لا تستطيع حسمها.""",
'ar-c2-u02-p06':"""وفي مراجعة عمياء صنف فريق ثان عشر حجج قصيرة بحسب موضع الخلاف من دون معرفة الوحدة التي جاءت منها. اتفق الفريق في معظمها، واختلف في حالتين تجمعان مشكلة معنى مع مشكلة سلطة. بدل إجبار كل حالة على خانة واحدة، سمح المدرس بوصف الخلاف على طبقتين وحدد أيهما يجب حله أولًا. أظهر التمرين أن الخرائط ليست صناديق منفصلة؛ قد يغير تفسير العبارة مقدار السلطة، وقد يكشف أثر التطبيق أن قراءة ما توسع المؤسسة أكثر مما ظنه القارئ أولًا. لكن ترتيب الأسئلة يظل مفيدًا لأنه يمنع القفز من أثر غير مرغوب إلى ادعاء لغوي لم يُبرهن. في النهاية صار الطلاب قادرين على ذكر ليس فقط القراءة التي يفضلونها، بل الحلقة التي إذا تغيرت ستجعلهم يغيرون ذلك التفضيل.""",
}
extra_code="EXTRA = "+repr(EXTRA)+"\nfor _pid,_extra in EXTRA.items():\n    ADD[_pid]=ADD[_pid].rstrip()+' '+_extra.strip()\n"
patched=text.replace(marker,extra_code+'\n'+marker,1)
exec(compile(patched,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
